namespace ghidra.app.cmd.label;

using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;

public class PinSymbolCmd : Command<Program> {

	private Address addr;
	private string name;
	private bool pin;
	private string message;

	public PinSymbolCmd(Address addr, string name, bool pin) {
		this.addr = addr;
		this.name = name;
		this.pin = pin;
	}

	/* @Override */
	public bool applyTo(Program program) {
		SymbolTable symbolTable = program.getSymbolTable();
		Symbol symbol = symbolTable.getGlobalSymbol(name, addr);
		if (symbol == null) {
			message = "Could not find symbol named " + name + " at address " + addr;
			return false;
		}
		symbol.setPinned(pin);
		return true;
	}

	/* @Override */
	public string getStatusMsg() {
		return message;
	}

	/* @Override */
	public string getName() {
		return "Set Pinned on " + name;
	}

}
